// importedCatalog is the set of NX-03 files the plan imports (30 files): only
// what the replay steps use, plus the two pings. The bearer files (two
// exchanges), the manifest HEADs (a read through the proxy caches), the
// "after-measures" files, the page n1/n2 files and the path/tags files are
// deliberately not imported.
func importedCatalog() []string {
	var names []string
	for _, id := range []string{"admin", "pull", "anon"} {
		for _, s := range []string{
			"catalog-group-connector-30482",
			"catalog-hosted-root-30481",
			"catalog-hosted-repository",
			"catalog-proxy-repository",
			"catalog-group-repository",
			"rest-repositories-docker-group",
			"rest-repositories-docker-hosted",
			"rest-repositories-docker-proxy",
			"rest-repositories-group-docker-group",
		} {
			names = append(names, s+"--"+id)
		}
	}
	names = append(names, "page-group-n1000--admin", "v2-ping-30481--anon", "v2-ping-30482--anon")
	sort.Strings(names)
	return names
}

func TestLoadCatalogIsTheImportedSet(t *testing.T) {
	fixtures, err := nexusfixture.Load("catalog")
	if err != nil {
		t.Fatalf("Load(catalog): %v", err)
	}
	var got []string
	for _, f := range fixtures {
		got = append(got, f.Name)
		if f.Campaign != "catalog" {
			t.Errorf("%s: Campaign = %q, want catalog", f.Name, f.Campaign)
		}
		if len(f.Exchanges) != 1 {
			t.Errorf("%s: %d exchanges, want 1 (no multi-exchange file is imported)", f.Name, len(f.Exchanges))
		}
		if f.Meta.NexusVersion != "3.98.1-01" || f.Meta.Edition != "COMMUNITY" || f.Meta.Measured != "2026-11-17" {
			t.Errorf("%s: Meta = {%q %q %q}, want {3.98.1-01 COMMUNITY 2026-11-17}",
				f.Name, f.Meta.NexusVersion, f.Meta.Edition, f.Meta.Measured)
		}
		if f.Meta.Record == "pending" {
			t.Errorf("%s is pending but Load returned it", f.Name)
		}
	}
	want := importedCatalog()
	if len(want) != 30 {
		t.Fatalf("test bug: the imported set has %d names, the plan says 30", len(want))
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Load(catalog) names (sorted by name) =\n%v\nwant\n%v", got, want)
	}
}

