		}
		if f.Meta.NexusVersion != "3.98.1-01" || f.Meta.Edition != "COMMUNITY" || f.Meta.Measured != "2026-11-17" {
			t.Errorf("%s: Meta = {%q %q %q}, want {3.98.1-01 COMMUNITY 2026-11-17}",
				f.Name, f.Meta.NexusVersion, f.Meta.Edition, f.Meta.Measured)
